def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    urgent_opponents = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if opp.get('budget', 0.0) > 200:
                    rich_pressure = max(rich_pressure, bid)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    danger = 0
    if hp <= 2 or no_water >= 2:
        danger = 3
    elif hp <= 4 or no_water >= 1:
        danger = 2
    elif hp <= 6:
        danger = 1

    base = 0.0

    if danger >= 3:
        base = max(62.0, highest_prev_bid + 2.0)
    elif danger == 2:
        if scarcity >= 1:
            base = max(48.0, highest_prev_bid * 0.55 + 6.0)
        else:
            base = max(38.0, avg_prev_bid * 0.35 + 5.0)
    else:
        if scarcity == 2:
            base = max(34.0, rich_pressure * 0.28 + 4.0)
        elif scarcity == 1:
            base = max(24.0, avg_prev_bid * 0.18 + 3.0)
        else:
            base = 12.0 + 2.0 * urgent_opponents

    if highest_prev_bid >= 150 and danger <= 1:
        base = min(base, 22.0)
    elif highest_prev_bid >= 120 and danger <= 1:
        base = min(base, 26.0)

    if day >= 8 and hp >= 5 and no_water == 0:
        base *= 0.9

    reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.12
    affordable = max(0.0, budget - reserve)
    if danger >= 2:
        affordable = budget

    bid = min(base, affordable, budget)

    if danger >= 2 and bid < 20.0 and budget >= 20.0:
        bid = min(budget, 20.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_pressures = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        # Use yesterday hp_after as a proxy for how hard they were hit
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                prev_pressures.append((float(hp_after), float(b) if b is not None else 0.0))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Supply pressure: moderate supply implies bidding competition; lower supply implies more aggressive bids.
    # Normalize supply to [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base bid level: try to slightly beat the top yesterday bid when it was large.
    # If highest was high, we match/undercut depending on our hp.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Opponents were willing to spend heavily; ensure we don't get squeezed.
        if hp <= 2 or no_water_days >= 2:
            target = max(highest_prev_bid * 0.98, second_prev_bid * 1.02)
        else:
            target = max(highest_prev_bid * 0.80, second_prev_bid * 1.05)
    else:
        # Otherwise, bid around a mid level to win water share without burning budget.
        # Higher supply => lower bid.
        mid = DAILY_SALARY * (0.62 - 0.25 * supply_norm)
        # If we have a competitor with a meaningful prior bid, nudge upward.
        target = max(mid, (second_prev_bid * 0.9 + highest_prev_bid * 0.1))

    # Convert target into a budget-safe bid with HP-aware risk control.
    # If low HP, be more aggressive; if high HP, conserve.
    if hp <= 1:
        cap = DAILY_SALARY * 0.95
    elif hp == 2:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * (0.70 - 0.10 * supply_norm)
        if cap < DAILY_SALARY * 0.45:
            cap = DAILY_SALARY * 0.45

    # If budget is very low, don't exceed it.
    bid = min(budget, target, cap)

    # Ensure non-negative and at least small bid if budget allows.
    if bid < 0.0:
        bid = 0.0

    # If we are at risk of immediate failure (no_water_days high), push harder.
    if no_water_days >= 3 and budget > 0:
        bid = min(budget, max(bid, DAILY_SALARY * 0.75))

    # If supply is extremely low within the range, increase slightly.
    if supply <= (MIN_SUPPLY + 1.0):
        bid = min(budget, bid * 1.10)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Base bid - a moderate amount
    base_bid = DAILY_SALARY * 0.5

    # Adjust bid based on my HP
    if my_status['hp'] <= 2: # Critical health
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4: # Low health
        base_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] <= 6 and day_context['day'] > EPISODE_DAYS / 2: # Mid-game, slightly low HP
        base_bid = DAILY_SALARY * 0.65

    # Adjust bid based on supply: more competition if supply is low
    # Supply range is [15, 25]. My requirement is 13.
    if day_context['supply'] <= WATER_REQ + 5: # Supply is tight (e.g., 15-18)
        base_bid = max(base_bid, DAILY_SALARY * 0.6) # Increase base bid if supply is scarce
    elif day_context['supply'] >= 20: # Supply is relatively abundant (e.g., 20-25)
        # Only reduce base bid if not already desperate
        if my_status['hp'] > 4:
            base_bid = min(base_bid, DAILY_SALARY * 0.45) # Decrease base bid if supply is high

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    proposed_bid = base_bid

    # Adjust bid based on opponent's previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If my HP is low or I'm already aiming for an aggressive bid, try to win
        if my_status['hp'] <= 4 or proposed_bid >= DAILY_SALARY * 0.7:
            proposed_bid = max(proposed_bid, highest_prev_bid + 2.0) # Bid slightly above highest previous
        else:
            # If highest bid was very high, but I'm not desperate, maybe don't match it fully
            if highest_prev_bid > DAILY_SALARY * 0.8:
                proposed_bid = max(proposed_bid, DAILY_SALARY * 0.6) # Don't overbid if not critical
            else:
                proposed_bid = max(proposed_bid, highest_prev_bid + 1.0) # Bid slightly above

    # Final check: ensure bid doesn't exceed budget and is at least 0
    final_bid = min(my_status['budget'], proposed_bid)
    return max(0.0, final_bid)

